-- =============================================================
-- 00013_seed_ctal_ta_f.sql
-- CTAL-TA テストアナリスト Set F -- テスト技法(Ch3)専科 / 40問
-- 題材: eラーニングプラットフォーム「まなびば」
-- 実出題で引っかかりやすいポイント(2値/3値BVAの混同、デシジョンテーブルの折りたたみ、
-- n-switchの計算、ペアワイズの保証範囲、代替/例外フローの区別など)に特化。
-- =============================================================

INSERT INTO public.subjects (slug, name, description, color, sort_order)
VALUES ('ctal-ta-f', 'CTAL-TA テストアナリスト Set F（技法専科）', 'ISTQB/JSTQB Advanced Level Test Analyst テスト技法(Ch3)に特化した模擬問題（全40問・実出題の引っ掛けパターンを重点強化）', '#7c3aed', 15)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.categories (subject_id, name, color, sort_order)
SELECT s.id, v.name, v.color, v.sort_order
FROM public.subjects s
CROSS JOIN (VALUES
  ('同値分割', '#58a6ff', 0),
  ('境界値分析', '#3fb950', 1),
  ('デシジョンテーブル', '#d2a8ff', 2),
  ('状態遷移テスト', '#e3a008', 3),
  ('組み合わせテスト', '#f778ba', 4),
  ('ユースケーステスト', '#79c0ff', 5),
  ('経験ベース技法', '#ff9492', 6),
  ('技法選択・メトリクス', '#94a3b8', 7)
) AS v(name, color, sort_order)
WHERE s.slug = 'ctal-ta-f'
ON CONFLICT (subject_id, name) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb, v.correct_index, v.correct_indices::jsonb, v.question_type, v.explanation_data::jsonb, 0
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('ctal-ta-f-q1', '同値分割',
   '「まなびば」の受講申込フォームには、氏名・メールアドレス・年齢の3つの入力項目があり、それぞれに無効な同値クラスが存在する。3項目すべてを同時に無効な値にした1つのテストケースを設計するのは、なぜ避けるべきか。',
   NULL,
   '["無効な同値クラスを複数含めると、テストケース数が技法上定められた上限を超えてしまうため。", "1つのテストケースに無効値を複数混ぜると、ある欠陥が別の欠陥をマスクし、原因の切り分けができなくなるため。", "複数の無効値を同時に使うと、システムが必ずクラッシュし、テスト環境の復旧に時間がかかってしまうため。", "無効な同値クラスは境界値分析専用の対象であり、同値分割のテストケースには含めるべきではないため。"]', 1, '[1]', 'single',
   '{"asked": "同値分割における単一障害の原則（無効クラスは1テストケースにつき1つ）の理由を理解しているか。", "kid": "無効な値を一度にたくさん混ぜると、どれが原因かわからなくなるから、1つずつ試す。", "terms": [["単一障害の原則", "1つのテストケースでは無効な入力を1つだけにし、他は有効にするという考え方。"]], "think": "体調不良の原因を調べるとき、複数の食べ物を同時に変えて食べると、どれが原因か分からなくなるのと同じ。", "vs": "クラッシュの有無や技法上の上限といった話ではなく、『原因の切り分けができなくなる』ことが単一障害の原則の本質的な理由。", "opt": ["同値分割の技法自体にテストケース数の上限が定められているわけではない。", "正解。原因の切り分けができなくなることが、無効値を混在させるべきでない本質的な理由。", "必ずクラッシュするとは限らず、また仮にクラッシュしても、それ自体が単一障害の原則の理由ではない。", "無効クラスは同値分割でも扱う通常の対象であり、境界値分析専用というのは誤り。"]}'),

  ('ctal-ta-f-q2', '同値分割',
   '「まなびば」のコース検索で、カテゴリ（プログラミング/デザイン/語学）とレベル（初級/中級/上級）という2つの有効な入力項目がある。同値分割の観点で、これらの有効な同値クラスをテストケースにする際、最も効率的な設計はどれか。',
   NULL,
   '["カテゴリとレベルの組み合わせをすべて（3×3＝9通り）網羅しない限り、有効な同値クラスをテストしたことにはならない。", "複数の入力項目の有効な同値クラスは、可能であれば1つのテストケースにまとめて複数を網羅してよい（無効クラスとは異なり、まとめることが許される）。", "有効な同値クラスも無効な同値クラスと同様に、必ず1つのテストケースにつき1項目だけを有効にし、残りは無効にしなければならない。", "有効な同値クラスは境界値分析の対象外であるため、同値分割では複数のクラスを個別に1件ずつテストする必要がある。"]', 1, '[1]', 'single',
   '{"asked": "有効な同値クラスは複数項目をまとめてテストしてよいという、無効クラスとの非対称性を理解しているか。", "kid": "『大丈夫な値』同士は一緒に試してOK。ダメな値だけは1つずつ分けて試す。", "terms": [["弱い同値分割", "各同値クラスから少なくとも1つの代表値を選び、複数項目をまとめてテストしてよい考え方。"]], "think": "買い物リストで、問題ない商品同士は一緒にカゴに入れてレジを通せるが、返品したい不良品は1つずつ個別に確認するイメージ。", "vs": "無効クラスの単一障害の原則（1つずつ分ける）と、有効クラスの効率化（まとめてよい）は対になる別々のルールであり、混同しやすい。", "opt": ["全組み合わせの網羅はペアワイズやデシジョンテーブルの話であり、同値分割の代表値選定の目的ではない。", "正解。有効クラスはまとめてテストしてよく、これが同値分割による工数削減の実務的な利点。", "有効クラスにまで単一障害の原則を適用するのは過度に厳格で、テストケース数が不必要に増える。", "有効クラスも境界値分析と組み合わせて使うことは可能で、対象外という記述は誤り。"]}'),

  ('ctal-ta-f-q3', '同値分割',
   '「まなびば」のクーポンコードは『英大文字5桁＋チェックデジット1桁』という規則で構成され、単純な文字数の範囲だけでなく、チェックデジットの計算式を満たすかどうかで有効/無効が決まる。この入力に同値分割を適用する際、最も適切な考え方はどれか。',
   NULL,
   '["同値分割は数値の連続範囲にのみ適用でき、計算ルールを持つ入力には適用できない技法である。", "チェックデジットの検証はホワイトボックス技法でしか確認できず、同値分割の対象外として扱うべきである。", "クーポンコードの形式チェックは境界値分析の対象であり、チェックデジットの正誤は同値分割の対象外である。", "数値の連続範囲でなくても、『チェックデジットが正しい』『形式は合っているが誤り』のように、業務ルール上の等価性でクラスを分けられる。"]', 3, '[3]', 'single',
   '{"asked": "同値分割が数値範囲に限らず、業務ルールに基づく等価性でも適用できることを理解しているか。", "kid": "数字の範囲じゃなくても、『ルールに合っている/いない』でグループ分けできる。", "terms": [["同値クラス", "入力の中で、システムが同じように扱うと期待されるグループ。"]], "think": "クイズの答え合わせで、『正解』と『形式は合っているが計算が間違っている解答』を別グループとして扱うイメージ。", "vs": "同値分割は『同じ振る舞いをするかどうか』という等価性に基づく技法であり、数値の連続範囲に限定される技法ではない。", "opt": ["数値範囲に限定されるという前提が誤り。同値分割はより広い『振る舞いの等価性』に基づく技法。", "チェックデジットの検証結果（有効/無効）というブラックボックスの振る舞いとして扱えるため、ホワイトボックス限定というのは誤り。", "境界値分析は主に数値・順序のある範囲に向く技法で、この入力の形式チェック自体は同値分割の対象になり得る。", "正解。業務ルール上の等価性（正しいか、形式は合っているが計算が違うか）でクラスを分けるのは正当な同値分割の適用。"]}'),

  ('ctal-ta-f-q4', '同値分割',
   '「まなびば」の通知設定で、メール通知の頻度は『即時／日次まとめ／週次まとめ／通知なし』の4択から選ぶ。この入力に対する同値分割の考え方として最も適切なものを選べ。',
   NULL,
   '["選択肢の数が4つと少ないため、同値分割ではなく状態遷移テストとして扱うべき入力である。", "数値範囲ではない離散的な選択肢の集合でも、それぞれが独立した同値クラスとみなせ、各クラスから代表値を1つずつ選んでテストする。", "離散的な選択肢は同値分割の対象にはならず、4つすべてを必ず境界値分析で確認しなければならない技法である。", "最も多くのユーザーが選ぶと想定される『日次まとめ』のみを代表として選び、他の3つは省略してよい。"]', 1, '[1]', 'single',
   '{"asked": "同値分割が数値範囲だけでなく、離散的な選択肢集合にも適用できることを理解しているか。", "kid": "選択肢が4つあれば、それぞれを1つのグループとして、4つとも試す。", "terms": [["離散値の同値クラス", "範囲ではなく、個別の選択肢そのものが同値クラスになる場合。"]], "think": "信号機の色（赤・黄・青）のように、選択肢がはっきり分かれているものは、それぞれが1つのグループとして扱える。", "vs": "境界値分析は『順序があり隣接する値』に向く技法で、順序に意味のない離散選択肢（頻度の種類）には同値分割の方が素直に当てはまる。", "opt": ["選択肢の数の少なさは技法選択の決定的な基準ではなく、順序や履歴依存の有無で判断すべき。", "正解。離散的な選択肢もそれぞれ独立した同値クラスとして扱い、各クラスから代表値を選ぶのが基本。", "離散的な選択肢にも同値分割は適用できる。境界値分析限定という記述は技法の適用範囲を誤解している。", "一部の選択肢を想定利用頻度だけで省略すると、他の選択肢固有の不具合を見逃すリスクが残る。"]}'),

  ('ctal-ta-f-q5', '境界値分析',
   '「まなびば」のクーポン割引率の入力欄は、1〜100（共に有効、単位は%）という整数の範囲を受け付ける。3値境界値分析でこの範囲に対して選ぶべきテスト値の組み合わせとして最も適切なものはどれか。',
   NULL,
   '["0, 1, 100, 101 の4点（各境界について、外側と内側を1点ずつ選ぶという2値境界値分析の考え方）。", "1, 50, 100 の3点（範囲の最小・中央・最大を選ぶという、同値分割の代表値の考え方）。", "0, 1, 2, 98, 99, 100 の6点（境界のすぐ内側から3点ずつ選び、範囲外の無効値である101は選ばない）。", "0, 1, 2, 99, 100, 101 の6点（各境界について、境界の値とその両隣を1点ずつ選ぶ）。"]', 3, '[3]', 'single',
   '{"asked": "3値境界値分析（各境界について境界値とその両隣の3点ずつ）と2値境界値分析の点数の違いを理解しているか。", "kid": "3値は境界とその両どなりの3点ずつ、2値は境界の内側と外側の2点ずつ。数え方が違う。", "terms": [["3値境界値分析", "各境界について、境界の値・その1つ下・その1つ上の3点を選ぶ境界値分析。"], ["2値境界値分析", "各境界について、境界のすぐ内側とすぐ外側の2点を選ぶ境界値分析。"]], "think": "崖のふちを調べるとき、崖の縁そのものに加えて、その手前と向こう側の両方を確認するのが3値、縁の内と外だけ確認するのが2値。", "vs": "『4点』は2値境界値分析の考え方であり、問題文の『3値』という指定と矛盾する。『3点』は同値分割の代表値選定の考え方で境界値分析とは別技法。", "opt": ["この4点は2値境界値分析の選び方であり、問題で指定されている3値境界値分析の点数としては不足している。", "この3点は同値分割の代表値の選び方に近く、境界そのものを狙う境界値分析の考え方とは異なる。", "101（範囲外の無効値）を含めないと上側の境界を外側から確認できておらず、3値境界値分析としては不完全。", "正解。1と100の各境界について、その値と両隣（0,1,2および99,100,101）を選ぶのが3値境界値分析。"]}'),

  ('ctal-ta-f-q6', '境界値分析',
   '「まなびば」のライブレッスンは同時視聴デバイス数が1台以上5台以下まで許容され、0台または6台以上では接続が拒否される。2値境界値分析で選ぶべきテスト値として最も適切なものはどれか。',
   NULL,
   '["0, 1, 2, 5, 6, 7 の6点（3値境界値分析の考え方を誤って2値の場面に適用してしまっている）。", "1, 5 の2点のみ（境界の値そのものだけを選び、隣接する値は選ばない）。", "0, 1, 5, 6 の4点。", "1, 2, 4, 5 の4点（範囲の内側の境界だけを選び、範囲外の無効値は選ばない）。"]', 2, '[2]', 'single',
   '{"asked": "2値境界値分析で無効値側を含めることと、境界の値そのものだけでは不十分であることを理解しているか。", "kid": "OKとNGの切り替わる場所の内側と外側、両方を1点ずつ見る。", "terms": [["無効な同値クラスの境界", "有効範囲のすぐ外側にある、拒否されるべき値。"]], "think": "エレベーターの定員が5人までなら、5人と6人（定員オーバー）の両方を確認しないと、定員オーバーが正しく防げているか分からない。", "vs": "無効値側（0や6）を含めないと『正しく拒否されるか』が確認できない。境界の値だけでは『すぐ外側で正しく切り替わるか』が確認できない。", "opt": ["この6点は3値境界値分析の考え方であり、2値境界値分析として問われている今回の設問には点数が過剰。", "境界の値そのものだけでは、そのすぐ外側で正しく切り替わっているかどうかまでは確認できない。", "正解。有効範囲の内側の境界（1,5）と無効範囲側（0,6）をあわせた4点が2値境界値分析の標準セット。", "無効値側（0や6）を確認しないと、範囲外の値が正しく拒否されるかどうかが検証できない。"]}'),

  ('ctal-ta-f-q7', '境界値分析',
   '「まなびば」の夏のキャンペーンは2026年8月1日から8月31日まで（両日を含む）実施される。境界値分析でテストすべき日付の組み合わせとして最も適切なものはどれか。',
   NULL,
   '["8月1日, 8月15日, 8月31日 の3点（月初・月中・月末を選ぶという同値分割の代表値の考え方）。", "7月31日, 8月1日, 8月31日, 9月1日 の4点。", "8月2日, 8月1日, 8月31日, 8月30日 の4点（月をまたがず、月内の値だけで境界を確認する）。", "7月1日, 8月1日, 8月31日, 9月30日 の4点（範囲の前後の月の代表的な日付を選ぶ）。"]', 1, '[1]', 'single',
   '{"asked": "日付という順序のあるが数値ではないデータへの境界値分析の適用と、月またぎの計算（カレンダー上の off-by-one）を正しく扱えるか。", "kid": "キャンペーンの前日・初日・最終日・翌日を確認する。月をまたぐ計算に注意。", "terms": [["順序尺度への境界値分析", "数値でなくても、順序関係がある入力（日付など）に境界値分析を適用できる。"]], "think": "お店の営業最終日とその翌日（定休日）をきちんと確認しないと、『閉店後もまだ買える』ような不具合を見逃す。", "vs": "月をまたがずに月内だけで隣接日を選ぶと、実際の境界（7月31日・9月1日）を見逃す。同値分割の代表値選定（月初・月中・月末）は境界値分析とは異なる考え方。", "opt": ["月初・月中・月末という選び方は同値分割の代表値の考え方に近く、境界そのものを狙う境界値分析とは異なる。", "正解。範囲の直前（7/31）・開始（8/1）・終了（8/31）・直後（9/1）の4点が境界値分析として正しい。", "月をまたいだ本当の境界（7月31日と9月1日）を確認しないと、範囲外での正しい拒否が検証できない。", "範囲から離れすぎた日付（7月1日、9月30日）は境界そのものの確認にはならず、境界値分析の狙いを外している。"]}'),

  ('ctal-ta-f-q8', '境界値分析',
   '「まなびば」の会員登録の年齢入力は、13歳未満は登録不可、13〜17歳は保護者同意が必要、18歳以上は同意不要という3区分になっている。境界値分析で確認すべき境界点の組み合わせとして最も適切なものはどれか。',
   NULL,
   '["12, 13, 17, 18 の4点（区分の変わり目である2つの境界について、それぞれ内側と外側を1点ずつ）。", "0, 1, 12, 13, 17, 18 の6点（下限のクラス開始点である0歳の周辺も、別の境界として追加で確認する）。", "12, 17 の2点のみ（各区分の境界の内側の値だけを選び、外側の値は選ばない）。", "13, 18 の2点のみ（各区分の開始点だけを選べば、境界値分析としては十分である）。"]', 0, '[0]', 'single',
   '{"asked": "複数の区分が隣接して並ぶ場合、境界は区分の『変わり目』の数だけ存在し、区分の開始点そのものが必ずしも別の境界を意味しないことを理解しているか。", "kid": "区分が変わるところ（12→13歳、17→18歳）だけが境界。0歳は区分の始まりであって新しい境界ではない。", "terms": [["境界の変わり目", "隣接する2つの同値クラスの間で振る舞いが変化する地点。"]], "think": "信号が赤から青に変わる瞬間だけを見ればよく、赤信号の『真ん中』を別途確認する必要はないのと同じ。", "vs": "0歳は範囲の開始点であって、そこで振る舞いが変化する『境界』ではない（0歳未満という別の無効クラスが明示的に定義されていない限り）。この設問では2つの境界（12/13、17/18）だけが対象。", "opt": ["正解。2つの区分の変わり目（12/13歳、17/18歳）それぞれについて内側・外側の1点ずつが境界値分析として正しい。", "0歳周辺は区分の開始点であり、明示的な下限の無効クラスが定義されていない限り、新たな境界として扱う根拠が薄い。", "内側の値（12,17）だけでは、境界のすぐ外側（13,18）で正しく区分が切り替わっているかまでは確認できない。", "開始点（13,18）だけでは、境界のすぐ内側（12,17）が正しく前の区分として扱われているかまでは確認できない。"]}'),

  ('ctal-ta-f-q9', '境界値分析',
   '「まなびば」のパスワードは8文字以上20文字以下でなければならない。2値境界値分析で選ぶべき文字数の組み合わせとして最も適切なものはどれか。',
   NULL,
   '["7文字, 8文字, 20文字, 21文字 の4点。", "8文字, 9文字, 19文字, 20文字 の4点（最小値・最大値を境界の内側の代表値として扱い、そこから1つ内側にずらす）。", "1文字, 8文字, 20文字, 100文字 の4点（極端に短い値と長い値も境界として追加する）。", "8文字, 20文字 の2点のみ（範囲の両端の文字数だけを確認すればよい）。"]', 0, '[0]', 'single',
   '{"asked": "『8文字以上』の境界が7/8であって8/9ではないという、off-by-oneを正確に扱えるか。", "kid": "『8文字以上』の切り替わりは7文字と8文字の間。8文字と9文字の間ではない。", "terms": [["最小値の境界", "有効範囲の最小値とその1つ手前の無効な値との境目。"]], "think": "ジェットコースターの『身長120cm以上』という条件は、119cmと120cmの間が境目であって、120cmと121cmの間ではない。", "vs": "『8,9,19,20』は境界を1つ内側にずらしてしまっており、本来無効であるはずの7文字・21文字を確認できていない典型的なoff-by-oneの誤り。", "opt": ["正解。7文字（無効）と8文字（有効）、20文字（有効）と21文字（無効）が正しい境界の組み合わせ。", "境界が1つ内側にずれており、本来無効となるべき7文字・21文字が範囲外として正しく拒否されるかを確認できていない。", "1文字や100文字は境界そのものではなく、極端な値を使うエラー推測に近い観点であり、境界値分析の最小構成としては過剰。", "両端の値だけでは、そのすぐ外側（7文字・21文字）で正しく拒否されるかどうかまでは確認できない。"]}'),

  ('ctal-ta-f-q10', '境界値分析',
   '境界値分析について、テスト担当者Aは『境界値分析を実施すれば、境界付近に潜む欠陥はすべて確実に検出できる』と説明した。この説明は正しいか。',
   NULL,
   '["正しくない。境界値分析は境界そのものではなく、範囲の中央付近の欠陥を検出するために使う技法だから。", "正しい。ただし境界値分析は数値以外の入力には一切適用できないという条件付きでのみ正しいと言える。", "正しくない。境界値分析は境界付近に欠陥が集中しやすいという経験則に基づく効率化技法で、検出を保証するものではない。", "正しい。境界値分析は数学的に境界上の欠陥の存在を証明する技法で、境界付近の欠陥を100%検出できる。"]', 2, '[2]', 'single',
   '{"asked": "境界値分析が『欠陥を検出しやすくする技法』であって『欠陥の検出を保証する技法』ではないことを理解しているか（技法の限界の理解）。", "kid": "境界値分析は『見つけやすくする』工夫であって、『絶対見つかる』保証ではない。", "terms": [["技法の限界", "どのテスト技法も、特定の種類の欠陥を検出しやすくするものであり、全欠陥の検出を保証するものではない。"]], "think": "健康診断で特定の検査を受けても、すべての病気が見つかるわけではなく、特定の病気を見つけやすくするだけ、というのと同じ。", "vs": "『数学的に証明』『100%検出』という言い切りは、あらゆるテスト技法に共通する『欠陥検出の保証はできない』という限界を無視した過大評価。", "opt": ["境界値分析はまさに境界（範囲の端）付近の欠陥を狙う技法であり、中央付近を狙う技法という説明は誤り。", "境界値分析は数値だけでなく、日付や文字数など順序のある入力全般に適用できるため、数値限定という条件は誤り。", "正解。境界付近に欠陥が集中しやすいという経験則に基づく効率化技法であり、検出を保証するものではない。", "境界値分析は経験則に基づく技法であり、欠陥の存在を数学的に証明したり100%検出を保証したりするものではない。"]}'),

  ('ctal-ta-f-q11', '境界値分析',
   '境界値分析が最も効果的に機能する入力の性質として最も適切なものはどれか。',
   NULL,
   '["画面から画面への遷移など、操作の順序や履歴に依存して結果が変わる入力。", "複数の独立した条件が複雑に組み合わさって、初めて1つの結果が決まる入力。", "数値や日付のように、順序関係があり、有効範囲と無効範囲の境目が明確に定義されている入力。", "選択肢の間に順序や大小関係がない、単純なラジオボタンやチェックボックスの選択項目。"]', 2, '[2]', 'single',
   '{"asked": "境界値分析が適する入力の性質（順序があり境目が明確な範囲）を、他技法が適する性質と区別できるか。", "kid": "『順番があって、ここまでOK・ここからNG』とはっきり分かれている入力に向いている。", "terms": [["境界値分析が適する入力", "順序関係があり、有効/無効の境目が明確な数値・日付等の範囲。"]], "think": "ものさしの目盛りのように、順番に並んでいて『どこからどこまでが有効か』がはっきりしているものに向く技法。", "vs": "順序のない選択肢はEP向き、履歴依存の振る舞いは状態遷移テスト向き、複数条件の組み合わせはデシジョンテーブル向きで、いずれも境界値分析が最も効果的な性質とは異なる。", "opt": ["操作の順序や履歴に依存する振る舞いは状態遷移テストが適した対象で、境界値分析の主眼とは異なる。", "複数条件の組み合わせによる結果決定はデシジョンテーブルが適した対象で、境界値分析の主眼とは異なる。", "正解。順序があり境目が明確な範囲を持つ入力こそ、境界値分析が最も効果的に機能する対象。", "順序のない選択肢には境目という概念が薄く、境界値分析よりも同値分割の方が素直に適合する。"]}'),

  ('ctal-ta-f-q12', 'デシジョンテーブル',
   '上記の8規則の生デシジョンテーブルにおいて、学生証提示=N・早期申込=Nの場合（R7・R8）はクーポン使用の有無にかかわらず結果が0%で変わらない。実務上、折りたたみ（collapse）を行った場合のデシジョンテーブルの規則数として最も適切なものはどれか。',
   '条件               R1   R2   R3   R4   R5   R6   R7   R8
学生証提示           Y    Y    Y    Y    N    N    N    N
早期申込             Y    Y    N    N    Y    Y    N    N
クーポン使用         Y    N    Y    N    Y    N    Y    N
結果:適用される割引   25%  20%  20%  15%  10%  10%  0%   0%',
   '["8規則。3条件×2値なので、常に2の3乗である8規則が必要であり、折りたたむことはできない仕組み。", "4規則。学生証提示とクーポン使用の2条件だけを考慮すればよく、早期申込は無視してよい仕組み。", "6規則。3条件のうち結果に影響しない組み合わせをすべて除外すると、6規則まで減らせる計算。", "7規則。R7とR8はクーポン使用の値に関わらず結果が同じなので、クーポン使用を『-』とした1行にまとめられる。"]', 3, '[3]', 'single',
   '{"asked": "『don''t care（-）』を使ったデシジョンテーブルの折りたたみの考え方と、その際の正しい規則数の計算を理解しているか。", "kid": "結果が同じで条件に関係ない部分は『-』にして、1つの行にまとめられる。", "terms": [["折りたたみ（collapse）", "結果に影響しない条件を『-（don''t care）』として複数の規則を1つにまとめること。"]], "think": "『雨でも晴れでも、平日なら会社に行く』という場合、天気の条件は『-』にして1つのルールにまとめられるのと同じ。", "vs": "『常に2の3乗』という考え方は、結果に影響しない条件があることを見落とした、生の組み合わせ数への固執。全条件を無視するのも、逆に折りたたみ可能な組み合わせを見落とすのも、どちらも正確な折りたたみの計算ではない。", "opt": ["結果に影響しない組み合わせ（R7・R8）が存在する以上、常に8規則のままとは限らず、折りたたみが可能。", "早期申込は他の規則（R1〜R6）では結果に影響しており、条件そのものを丸ごと無視するのは誤り。", "影響しない組み合わせは今回R7・R8の1組だけであり、6規則という数字は折りたたみの範囲を過大に見積もっている。", "正解。R7とR8は結果が同じでクーポン使用が無関係なので1行にまとめられ、8-1＝7規則になる。"]}'),

  ('ctal-ta-f-q13', 'デシジョンテーブル',
   '「まなびば」の会員種別は『無料会員』『プレミアム会員』のいずれか一方のみで、両方に同時に該当することはない。この会員種別を条件の1つとしてデシジョンテーブルを作る場合、最も適切な考え方はどれか。',
   NULL,
   '["会員種別は『無料』『プレミアム』という2つの独立した条件として別々に用意し、両方Y・両方Nを含む2の2乗＝4通りをすべて規則として作らなければならない。", "会員種別のような相互排他的な条件はデシジョンテーブルでは扱えないため、別の技法（状態遷移テスト）に置き換える必要がある。", "会員種別を条件に含めると規則数が複雑になりすぎるため、デシジョンテーブルからは除外し、別途手動で確認する。", "会員種別を1つの条件として『無料／プレミアム』の2値で扱い、両方が同時にYになる組み合わせは論理的に存在しないため、その行は規則から除外してよい。"]', 3, '[3]', 'single',
   '{"asked": "相互排他的な条件（同時に真になり得ない組み合わせ）を持つデシジョンテーブルが、必ずしも2^nの全規則を必要としないことを理解しているか。", "kid": "『同時には起こらない組み合わせ』は最初から除いてよい。", "terms": [["論理的に不可能な組み合わせ", "条件同士の関係上、実際には起こりえない条件の組み合わせ。"]], "think": "信号が同時に赤と青にはならないのと同じで、あり得ない組み合わせをテーブルに含める必要はない。", "vs": "2つの独立条件として扱うと、本来あり得ない『両方Y』『両方N』という組み合わせまで規則に含めてしまい、無意味な規則を作ることになる。", "opt": ["独立した2条件として扱うと、本来起こりえない組み合わせまで規則に含めてしまい、無駄で誤解を招く規則が生まれる。", "相互排他的な条件はデシジョンテーブルでも普通に扱え、状態遷移テストへの置き換えが必須というわけではない。", "条件が複雑になることは除外の理由にはならず、むしろ適切に条件を定義すれば複雑さは制御できる。", "正解。1つの条件（2値）として扱い、あり得ない組み合わせを最初から除外するのが実務的で正しいアプローチ。"]}'),

  ('ctal-ta-f-q14', 'デシジョンテーブル',
   '「まなびば」の返金ポリシーに関するデシジョンテーブルで、明示的に列挙した規則以外の残りの組み合わせをすべて『規則Z: 返金不可（デフォルト）』としてまとめて扱う設計がある。この設計についての評価として最も適切なものはどれか。',
   NULL,
   '["妥当でない。デシジョンテーブルはすべての組み合わせを個別の規則として明示的に列挙しない限り、完全なテーブルとは認められない。", "妥当でない。else規則を使うと、条件の組み合わせが2の n乗を超えてしまい、テーブルとして矛盾が生じる。", "妥当である。ただしelse規則を使った場合、そのテーブルはもはやデシジョンテーブルではなく状態遷移図として扱うべきである。", "妥当である。個別に列挙されていない残りの組み合わせを網羅する『else（デフォルト）規則』を使うことで、完全性を保ちながら規則数を減らせる。"]', 3, '[3]', 'single',
   '{"asked": "『else（デフォルト）規則』を用いても、残りの組み合わせを漏れなくカバーしていれば完全なデシジョンテーブルとみなせることを理解しているか。", "kid": "『その他ぜんぶ』をまとめた規則を1つ作っても、漏れがなければちゃんとしたテーブルと言える。", "terms": [["else（デフォルト）規則", "個別に列挙されていない残りの組み合わせをまとめて扱う規則。"]], "think": "利用規約で『上記以外の場合は運営の判断による』とまとめて書いても、それが規約全体の抜けを意味しないのと同じ。", "vs": "個別列挙が必須という考え方は、else規則によって完全性を保ちながら規則数を減らせるという実務的な工夫を見落としている。else規則の使用が組み合わせ数の矛盾や技法の変更を意味するわけでもない。", "opt": ["個別列挙が必須という考え方は厳格すぎ、else規則による効率化という実務上一般的な手法を否定してしまう。", "else規則は組み合わせ数そのものを変えるものではなく、残りの組み合わせをまとめて表現する記法にすぎない。", "else規則を使ってもテーブルはデシジョンテーブルのままであり、状態遷移図に変わるわけではない。", "正解。else規則は残りの組み合わせを漏れなくまとめる正当な手法で、完全性を保ちながら規則数を減らせる。"]}'),

  ('ctal-ta-f-q15', 'デシジョンテーブル',
   'デシジョンテーブルにおいて、異なる条件の組み合わせ（規則）であっても、導かれる結果（アクション）が同じになる規則が複数ある場合、テストケースの設計として最も適切な考え方はどれか。',
   NULL,
   '["結果が同じ規則が複数あること自体がデシジョンテーブルの設計ミスを意味し、テーブルを作り直す必要がある。", "結果が同じ規則同士は、実装上も必ず同じコードパスを通るため、テストする必要性は特にない。", "結果が同じでも規則（条件の組み合わせ）自体が異なるなら、それぞれ別規則として少なくとも1つずつテストケースを用意すべきである。", "結果が同じ規則同士は、テストケースとしては1つにまとめてよく、残りの規則のテストはすべて省略してよい。"]', 2, '[2]', 'single',
   '{"asked": "『結果が同じ＝テストしなくてよい』という誤解に対し、条件の組み合わせが異なれば別々にテストすべき理由を理解しているか。", "kid": "答えが同じでも、たどってきた道（条件）が違うなら、それぞれ試す。", "terms": [["規則のテストケース化", "各規則ごとに少なくとも1つのテストケースを用意する基本方針。"]], "think": "同じ目的地（結果）にたどり着く道が複数あるとき、どの道も実際に安全に通れるかを別々に確認する必要があるのと同じ。", "vs": "『結果が同じなら省略してよい』という発想は、実装が条件ごとに異なる処理パスを通っている可能性（それぞれ別々に不具合が潜みうる）を見落としている。", "opt": ["結果が同じ規則が複数存在すること自体は珍しくなく、必ずしも設計ミスを意味しない。", "結果が同じでも実装上のコードパスが同じとは限らず、その前提自体が確認されていない誤った思い込み。", "正解。条件の組み合わせが違えば、実装上のパスも異なりうるため、結果が同じでも別々にテストすべき。", "結果が同じだからと省略すると、特定の条件の組み合わせでのみ起こる不具合を見逃すおそれがある。"]}'),

  ('ctal-ta-f-q16', 'デシジョンテーブル',
   '複雑な論理関係（AND/OR/NOTの組み合わせ）を持つ要件から、デシジョンテーブルを体系的に導出するために使われる図式表現の技法は何か。',
   NULL,
   '["状態遷移図。状態と遷移を矢印で表す図であり、条件同士の論理関係を表すためのものではない技法。", "ペアワイズテスト。組み合わせ爆発を抑えるための技法であり、論理関係を図式化する技法ではない。", "原因結果グラフ。条件（原因）と結果を論理関係で結んだグラフを作り、そこからデシジョンテーブルを導く技法。", "クラシフィケーションツリー技法。入力を階層的な分類木で表現する技法で、論理関係の表現には向いていない。"]', 2, '[2]', 'single',
   '{"asked": "原因結果グラフがデシジョンテーブルを導出するための関連技法であることを理解しているか（デシジョンテーブルと同一ではなく、導出の前段階）。", "kid": "『原因と結果の関係』を図にして整理してから、デシジョンテーブルの形にする技法。", "terms": [["原因結果グラフ", "条件（原因）と結果の論理的な関係を図で表し、デシジョンテーブルを導出するための技法。"]], "think": "料理のレシピの前に、材料同士の相性関係を図にまとめてから手順表（デシジョンテーブル）を作るようなイメージ。", "vs": "クラシフィケーションツリー・状態遷移図・ペアワイズはいずれも別の目的を持つ技法で、複雑な論理関係を図式化してデシジョンテーブルを導く役割は原因結果グラフに固有のもの。", "opt": ["状態遷移図は状態と遷移の表現が目的であり、条件の論理関係を表す技法ではない。", "ペアワイズは組み合わせ数を減らす選定技法であり、論理関係を図式化してテーブルを導出する技法ではない。", "正解。原因結果グラフは複雑な論理関係を整理し、デシジョンテーブルを体系的に導出するための技法。", "クラシフィケーションツリーは入力の階層的分類が主目的で、論理的なAND/OR関係の表現には向かない技法。"]}'),

  ('ctal-ta-f-q17', 'デシジョンテーブル',
   'デシジョンテーブルテストにおいて、『完全なテーブル』であることの説明として最も適切なものはどれか。',
   NULL,
   '["すべての規則の結果（アクション）が、互いにすべて異なっている状態。", "起こりうる条件の組み合わせが、個別の規則としてであれ、折りたたみやelse規則によってであれ、漏れなくカバーされている状態。", "すべての条件の組み合わせが、折りたたみやelse規則を一切使わずに、個別の規則として1行ずつ列挙されている状態。", "規則の数が必ず偶数になっている状態（条件数にかかわらず、規則数は常に偶数でなければならない）。"]', 1, '[1]', 'single',
   '{"asked": "『完全性』が『個別列挙の有無』ではなく『組み合わせの漏れの有無』で判断されることを理解しているか。", "kid": "『まとめてあっても、その他規則があっても、漏れがなければ完全』ということ。", "terms": [["完全なデシジョンテーブル", "起こりうる条件の組み合わせを漏れなくカバーしているテーブル。"]], "think": "出席簿で、全員の出欠がどこかに（個別にでも、まとめてでも）記録されていれば『漏れがない』と言えるのと同じ。", "vs": "個別列挙の有無や規則数の偶奇、結果の重複有無は完全性の定義そのものではなく、完全性はあくまで『組み合わせの漏れがないか』で判断される。", "opt": ["結果が同じ規則が複数あっても、組み合わせ自体に漏れがなければ完全なテーブルであり得る。", "正解。折りたたみやelse規則を使っていても、組み合わせに漏れがなければ完全なテーブルと言える。", "個別列挙は完全性の必須条件ではなく、折りたたみやelse規則を使っても完全性は保てる。", "規則数の偶奇は完全性とは無関係で、条件数や折りたたみの有無によって奇数になることも普通にある。"]}'),

  ('ctal-ta-f-q18', '状態遷移テスト',
   '状態遷移図の0-switchカバレッジ（すべての遷移を少なくとも1回通る）について、『1本のテストケース（開始から終了までの1つの実行パス）だけでは達成できない場合がある』理由として最も適切なものはどれか。',
   NULL,
   '["遷移の数が状態の数より多い場合は、必ず1本のテストケースでは網羅できないと定義で決まっているため。", "一部の未通過の遷移へ後から戻れない構造（一筆書きできない有向グラフ）の場合、複数のテストケースに分けて全遷移を網羅する必要があるため。", "0-switchカバレッジは定義上、常に複数のテストケースを必要とする技法として決められているため。", "0-switchは実行するテストケースの本数とは無関係で、実行順序だけに関係する概念だから、1本では成立しないため。"]', 1, '[1]', 'single',
   '{"asked": "0-switchカバレッジの達成に必要なテストケース本数が、状態遷移図の構造（一筆書き可能かどうか）に依存することを理解しているか。", "kid": "行ったきり戻れない道がある図では、1回の旅では全部の道を通れないことがある。", "terms": [["0-switchカバレッジ", "定義されているすべての単一遷移を、少なくとも1回通るカバレッジ基準。"]], "think": "すべての道を1回ずつ通りたい郵便配達人が、行き止まりの多い街では1周では回りきれず、複数回に分けて配達するのと同じ。", "vs": "『定義上常に複数必要』『本数と無関係』『遷移数が状態数より多いと必ず』はいずれも、実際は図の具体的な構造（戻れるかどうか）に依存するという本質を無視した過度な一般化。", "opt": ["遷移数と状態数の単純な大小比較だけでは、一筆書き可能かどうかは決まらない。", "正解。一筆書きできない構造の場合、複数のテストケースに分けなければ全遷移を網羅できない。", "0-switchの達成に必要な本数は図の構造に依存し、常に複数必要と決められているわけではない（単純な循環構造なら1本で足りることもある）。", "0-switchはまさにテストケース（実行パス）で遷移をどう通るかに関係する概念であり、無関係という説明は誤り。"]}'),

  ('ctal-ta-f-q19', '状態遷移テスト',
   '「まなびば」のコースは『未登録(U)→登録済(R)→受講中(S)→修了(F)』と進み、受講中(S)からは『一時停止(P)』にも遷移でき、一時停止(P)からは受講中(S)に戻れる。定義されている遷移は U→R, R→S, S→P, P→S, S→F の5つである。0-switchカバレッジを達成するために確認すべき遷移の総数はいくつか。',
   NULL,
   '["6（遷移の総数に、開始状態への最初の遷移を1つ余分に加えた数）。", "10（1-switchカバレッジで数える遷移ペアの数と混同した数）。", "5（定義されている遷移の総数と同じ）。", "4（状態の数から1を引いた、単純な直線的な遷移だけを数えた数）。"]', 2, '[2]', 'single',
   '{"asked": "0-switchカバレッジが確認する対象が『定義された遷移の総数』そのものであることを、具体的な図から正確に数えられるか。", "kid": "矢印（遷移）が5本あるから、確認すべき数も5個。", "terms": [["0-switchカバレッジ", "定義されている個々の遷移（矢印）を少なくとも1回ずつ確認するカバレッジ基準。"]], "think": "地図上の道（矢印）が5本あれば、すべての道を確認するには5本分のチェックが必要、というシンプルな数え方。", "vs": "『状態数-1』は分岐のない単純な一本道の場合にしか成り立たない数え方で、この図はS→PとP→Sの分岐・往復があるため当てはまらない。1-switch（遷移のペア）の数と混同しないよう注意。", "opt": ["0-switchは定義された遷移そのものを数える基準であり、開始状態への遷移を別枠で余分に加える必要はない。", "10は1-switch（連続する2つの遷移のペア）を数える際の値に近く、0-switchの数え方とは異なる。", "正解。定義されている遷移（矢印）は5本なので、0-switchカバレッジで確認すべき対象も5。", "状態数から1を引く数え方は、分岐や往復のない単純な一本道の場合にしか成り立たず、この図には当てはまらない。"]}'),

  ('ctal-ta-f-q20', '状態遷移テスト',
   '同じ状態遷移図（U→R, R→S, S→P, P→S, S→F の5遷移、S以降はFで終端）について、1-switchカバレッジ（連続する2つの遷移のペア）で確認すべき遷移ペアの数はいくつか。',
   NULL,
   '["5（0-switchカバレッジで数えた遷移の総数と、そのまま同じ数を答えてしまっている）。", "10（0-switchの遷移数5を、深く考えずに単純に2倍しただけの数である）。", "25（遷移の総数5を、深く考えずに単純に2乗しただけの数である）。", "6（U→R→S、R→S→P、R→S→F、S→P→S、P→S→P、P→S→F の6ペア）。"]', 3, '[3]', 'single',
   '{"asked": "1-switchカバレッジが『連続してつながる遷移のペア』であり、単純に遷移数を2倍・2乗するものではないことを、具体的な図から正確に数えられるか。", "kid": "『矢印→次の矢印』のつながりを数える。図をたどって実際に何本つながるか数えないといけない。", "terms": [["1-switchカバレッジ", "ある遷移の直後に続く別の遷移との組み合わせ（遷移のペア）をすべて確認するカバレッジ基準。"]], "think": "しりとりで『どの単語の次にどの単語が来られるか』を実際につながりをたどって数えるのに似ていて、単純な掛け算では出せない。", "vs": "『0-switchと同じ5』『2倍の10』『2乗の25』はいずれも、実際に図をたどって『つながる遷移のペア』を数えるという1-switchの定義を無視した単純計算の誤り。", "opt": ["1-switchは連続する2遷移のペアを数える基準であり、単一遷移を数える0-switchの値とは本来異なる概念・異なる値になりうる。", "遷移数を単純に2倍する計算は、実際につながっているペアの数（図の構造）を反映しておらず正しくない。", "遷移数を2乗する計算は、実際にはつながらない組み合わせまで数えてしまっており、1-switchの定義に合わない。", "正解。図を実際にたどると、つながる遷移のペアは6通りあり、これが1-switchカバレッジで確認すべき数。"]}'),

  ('ctal-ta-f-q21', '状態遷移テスト',
   '「まなびば」のコース受講状態は『受講中(S)』から『修了(F)』へ遷移するが、その遷移には『最終テストに合格した場合』と『管理者が手動で修了扱いにした場合』という2つの異なるトリガー（引き金となる条件）が存在する。テスト設計として最も適切な考え方はどれか。',
   NULL,
   '["同じ『S→F』という遷移先であっても、トリガーが異なれば論理的に別の遷移とみなし、それぞれ別のテストケースで確認する。", "遷移先の状態（F）が同じであれば、トリガーの違いにかかわらず1つのテストケースで確認すれば十分である。", "手動での修了扱いは正規の遷移ではなく例外的な操作なので、そもそもテスト対象に含めるべきではない。", "トリガーの違いは状態遷移テストの対象外であり、別途デシジョンテーブルで扱うべき話である。"]', 0, '[0]', 'single',
   '{"asked": "同じ遷移先でもトリガー（引き金）が異なれば別の遷移として扱うべきという、状態遷移テストの実務的な粒度を理解しているか。", "kid": "同じゴールに着いても、たどった理由（きっかけ）が違えば別々に確認する。", "terms": [["トリガー（イベント）", "状態遷移を引き起こすきっかけとなる出来事や条件。"]], "think": "同じ『退院』という結果でも、『治って退院』と『本人の希望で退院』は別々に医療プロセスとして確認すべきなのと同じ。", "vs": "『遷移先が同じなら1つで十分』という考え方は、それぞれのトリガーに応じて内部処理が異なる可能性（自動判定のロジックと管理者操作のロジックは別の実装パス）を見落としている。", "opt": ["正解。トリガーが異なれば実装上の処理経路も異なりうるため、論理的に別の遷移として個別にテストすべき。", "遷移先が同じでも、内部処理がトリガーごとに異なる可能性があり、1つにまとめると片方の不具合を見逃すおそれがある。", "手動操作による遷移も業務上定義された正規の遷移であり、テスト対象から除外すべき理由にはならない。", "トリガーの違いはまさに状態遷移テストが扱う対象であり、デシジョンテーブルに委ねるべき話ではない。"]}'),

  ('ctal-ta-f-q22', '状態遷移テスト',
   '「まなびば」の『受講中』状態は、内部的にさらに『動画視聴中』『クイズ受験中』という2つのサブ状態（子状態）を持つ階層的な状態機械として設計されている。テスト設計として最も適切な考え方はどれか。',
   NULL,
   '["サブ状態を持つ階層的な状態機械は状態遷移テストの対象外であり、探索的テストのみで確認すべきである。", "サブ状態間の遷移はテスト技法の対象にはならない実装の詳細であり、テストアナリストが関与する範囲ではない。", "上位の『受講中』レベルの遷移テストに加えて、サブ状態（動画視聴中／クイズ受験中）間の遷移についても別途カバレッジを確保する必要がある。", "サブ状態は上位状態に完全に含まれるため、上位レベルの状態遷移テストさえ実施すれば、サブ状態固有の不具合も自動的に検出できる。"]', 2, '[2]', 'single',
   '{"asked": "階層的な状態機械（super-state/sub-state）において、上位レベルの網羅だけではサブ状態固有の振る舞いを見逃す可能性があることを理解しているか。", "kid": "大きな部屋（受講中）の中に小部屋（動画視聴中・クイズ受験中）があるなら、小部屋の中の動きも別に確認する。", "terms": [["階層的な状態機械", "上位の状態がさらに内部にサブ状態を持つ、入れ子構造の状態機械。"]], "think": "会社の組織図で、部署（上位状態）の異動だけでなく、部署内のチーム（サブ状態）間の異動も別途確認しないと、チーム内特有の問題を見逃す。", "vs": "『上位さえ確認すれば自動的に検出できる』という考え方は、サブ状態固有の遷移や振る舞いが上位レベルのテストでは網羅されないことを見落としている。", "opt": ["階層的な状態機械も状態遷移テストの対象として扱えるものであり、探索的テストに限定する理由はない。", "サブ状態間の遷移もユーザーの振る舞いに関わる要素であり、テストアナリストが関与すべき対象になり得る。", "正解。上位レベルの網羅だけではサブ状態固有の不具合を見逃す可能性があり、別途カバレッジが必要。", "上位レベルのテストだけでサブ状態の不具合まで自動的に検出できるとは限らず、過度な楽観視。"]}'),

  ('ctal-ta-f-q23', '状態遷移テスト',
   '状態遷移テストで、定義されていない（無効な）遷移を漏れなく洗い出すために、状態遷移図よりも状態遷移表（状態×イベントのマトリクス）の方が優れているとされる理由として最も適切なものはどれか。',
   NULL,
   '["状態遷移表は状態遷移図と異なり、正常な遷移のみを対象とし、無効な遷移という概念自体を扱わない。", "状態遷移表ではすべての状態とイベントの組み合わせがマス目として明示され、定義されていない空欄の組み合わせが一目でわかる。", "状態遷移表は状態遷移図よりも図として理解しやすく、開発者への説明資料として優れているという理由による。", "状態遷移表は無効な遷移を自動的に除去する機能を持つため、テスト担当者が確認する手間が省ける仕組み。"]', 1, '[1]', 'single',
   '{"asked": "状態遷移表が『状態×イベント』のマトリクスとして、定義されていない組み合わせを明示的な空欄として可視化できることを理解しているか。", "kid": "表にすると、『まだ何も書いていないマス』がひと目でわかるので、抜けている組み合わせに気づきやすい。", "terms": [["状態遷移表", "状態を行、イベントを列（またはその逆）としたマトリクスで、各組み合わせの遷移先や無効性を示す表。"]], "think": "出席簿の空欄がひと目でわかるように、表にすると『まだ確認していない組み合わせ』が視覚的にすぐ見つかる。", "vs": "『理解しやすさ』は副次的な利点であり、無効な遷移を漏れなく洗い出せる本質的な理由ではない。表が無効な遷移を自動的に除去するわけでも、無効な遷移という概念自体を扱わないわけでもない。", "opt": ["状態遷移表もまさに無効な遷移（空欄や明示的な×印）を扱うための表現形式であり、扱わないという説明は誤り。", "正解。マトリクスの空欄として、定義されていない組み合わせが視覚的に明示されることが本質的な理由。", "理解しやすさは副次的な効果であり、無効な遷移を漏れなく洗い出せる本質的な理由の説明にはなっていない。", "状態遷移表は自動的に何かを除去する機能を持つものではなく、あくまで人が確認しやすくするための表現形式。"]}'),

  ('ctal-ta-f-q24', '組み合わせテスト',
   '「まなびば」の動画再生環境（デバイス3種×ブラウザ4種×通信速度2種）に対してペアワイズテストを実施し、生成された少数のテストケースをすべて実行して合格した。この結果から言えることとして最も適切なものはどれか。',
   NULL,
   '["任意の2因子間の組み合わせは網羅されているが、特定の3因子が同時に特定の値になったときにのみ発生する不具合は、見逃されている可能性がある。", "3因子すべての組み合わせが網羅されているため、いかなる組み合わせに起因する不具合も存在しないと言い切れる。", "ペアワイズテストは網羅性を保証しない技法なので、この結果からは因子同士の組み合わせについて何も言えない。", "デバイス・ブラウザ・通信速度のうち、最も影響の大きい1因子だけが正しく動作していることが確認できたにすぎない。"]', 0, '[0]', 'single',
   '{"asked": "ペアワイズテストが『2因子間の組み合わせ』を保証する技法であり、3因子以上の同時発生条件までは保証しないという限界を理解しているか。", "kid": "2つずつの組み合わせは確認できているけど、3つが同時に重なったときだけ起こる問題は見逃すかもしれない。", "terms": [["ペアワイズテストの限界", "任意の2因子間の組み合わせは網羅するが、3因子以上の同時条件までは保証しない。"]], "think": "2人1組の相性は全部チェックしたけれど、3人同時に集まったときだけ起きる特別な化学反応までは確認できていない、というイメージ。", "vs": "『3因子すべて網羅』は技法の保証範囲を過大評価した誤り。『何も言えない』は技法の効果（2因子間の網羅）を過小評価した誤り。『1因子だけ』は組み合わせ技法を単一因子の確認と取り違えている。", "opt": ["正解。2因子間の網羅は保証されるが、3因子同時条件でのみ発生する不具合までは保証されない。", "ペアワイズが保証するのは2因子間の組み合わせであり、3因子すべての組み合わせの網羅は保証されない。", "2因子間の組み合わせについては具体的な保証があり、『何も言えない』というのは技法の効果を過小評価している。", "ペアワイズは複数因子の組み合わせを確認する技法であり、単一因子だけの確認にとどまるものではない。"]}'),

  ('ctal-ta-f-q25', '組み合わせテスト',
   '組み合わせテストにおける『直交表（orthogonal array）』と『ペアワイズ（オールペア法）』の関係として最も適切な記述はどれか。',
   NULL,
   '["直交表はブラックボックス技法、ペアワイズはホワイトボックス技法という、系統自体が異なる技法である。", "両者とも組み合わせ数を削減する目的は共通するが、直交表は出現バランスが数学的に厳密な構造を持ち、ペアワイズは発見的な手法である。", "直交表とペアワイズは全く同じアルゴリズムを指す別名にすぎず、実務上わざわざ区別する必要はない用語。", "直交表は2因子間の網羅を保証しない技法で、ペアワイズだけが2因子間の網羅を保証する技法である。"]', 1, '[1]', 'single',
   '{"asked": "直交表とペアワイズ（オールペア法）が『目的は近いが構造の厳密さが異なる』別々の手法であることを理解しているか。", "kid": "どちらも組み合わせを減らす工夫だけど、直交表の方がよりきっちり数学的に整った作り方をする。", "terms": [["直交表", "各値の組み合わせの出現回数が均等になるよう数学的に設計された表。"], ["ペアワイズ（オールペア法）", "任意の2因子間の組み合わせ網羅を、発見的なアルゴリズムで達成する手法。"]], "think": "どちらも『効率よく献立を組む』工夫だが、直交表はきっちり栄養バランスを計算し尽くした献立表、ペアワイズはおおよそバランスよく品数を絞る工夫、というイメージの違い。", "vs": "『全く同じ』という説明は両者の構造上の厳密さの違いを無視している。『どちらか一方だけが2因子間を保証する』『技法の系統がブラック/ホワイトボックスで異なる』はどちらも誤った切り分け。", "opt": ["両者はいずれもブラックボックス寄りの組み合わせ技法であり、ホワイトボックス技法との対比は不適切。", "正解。目的は近いが、直交表は数学的に厳密な構造を持ち、ペアワイズはより発見的な手法という違いがある。", "両者は目的が近い別々の手法であり、アルゴリズムが完全に同一というわけではない。", "直交表もペアワイズも、いずれも2因子間の組み合わせ網羅を目的とする点では共通している。"]}'),

  ('ctal-ta-f-q26', '組み合わせテスト',
   '「まなびば」の動画再生環境の全組み合わせ数を計算したい。デバイス3種×ブラウザ4種×OS2種×通信速度2種の場合、全組み合わせ数として正しいものはどれか。',
   NULL,
   '["24通り（デバイスとブラウザの組み合わせ12通りのみを数え、OSと通信速度は考慮していない）。", "16通り（4因子のうち最大の水準数である4を、因子の数である4回掛けた数）。", "48通り（3×4×2×2）。", "11通り（3＋4＋2＋2、各因子の水準数を単純に足し合わせた数）。"]', 2, '[2]', 'single',
   '{"asked": "複数因子の全組み合わせ数が各因子の水準数の掛け算（積）で求まることを、正確に計算できるか。", "kid": "組み合わせの数は、それぞれの選択肢の数を全部掛け算する。3×4×2×2＝48。", "terms": [["組み合わせ爆発", "因子や水準数が増えるほど、全組み合わせ数が掛け算的に急増すること。"]], "think": "服のコーディネートで、トップス3種×ボトムス4種×靴2種×バッグ2種なら、全部の組み合わせは掛け算で数える。", "vs": "足し算にする、因子の一部を数え忘れる、同じ数（最大水準数）で代用して掛けるのは、いずれも各因子固有の水準数を正しく掛け合わせていない典型的な計算ミス。", "opt": ["4因子すべてが組み合わせに影響するため、一部の因子（OS・通信速度）を考慮に入れないのは計算漏れ。", "各因子はそれぞれ異なる水準数を持っており、代表として1つの数（4）だけを繰り返し掛けるのは誤り。", "正解。3×4×2×2＝48通りが、4因子すべてを正しく掛け合わせた全組み合わせ数。", "組み合わせ数は各因子の水準数を掛け合わせるのであって、足し合わせるものではない。"]}'),

  ('ctal-ta-f-q27', '組み合わせテスト',
   'クラシフィケーションツリー技法で入力の分類木を作成したあと、実際にテストケースとして選ぶ組み合わせの決め方について、最も適切な記述はどれか。',
   NULL,
   '["分類木を作った後も、単一値網羅・ペアワイズ網羅・全組み合わせ網羅など、複数ある組み合わせ選定戦略のいずれかを別途選ぶ必要がある。", "分類木を作成した時点で、テストケースとして選ぶべき組み合わせは自動的に1通りに一意に決まる。", "クラシフィケーションツリー技法では、組み合わせの選定という概念自体が存在せず、分類木の作成だけで技法が完結する。", "分類木を作成した後は、必ずすべての組み合わせを網羅しなければならず、他の選定戦略を選ぶ余地はない。"]', 0, '[0]', 'single',
   '{"asked": "クラシフィケーションツリー技法が『分類木の作成』と『組み合わせの選定』という2段階から成り、後者に複数の戦略があることを理解しているか。", "kid": "分類木を作った後も、『どの組み合わせを実際に試すか』は別途選ばないといけない。", "terms": [["組み合わせ選定戦略", "分類木ができた後、実際にテストする組み合わせの範囲を決める方針（単一値・ペアワイズ・全組み合わせ等）。"]], "think": "食材を分類した表を作った後も、『どの組み合わせで料理を作るか』は別途決める必要があるのと同じで、表を作っただけでは献立は決まらない。", "vs": "『自動的に一意に決まる』『概念が存在しない』『必ず全組み合わせ』は、いずれも分類木の作成と組み合わせ選定という2段階のプロセスを1段階に混同した誤り。", "opt": ["正解。分類木の作成後、複数ある組み合わせ選定戦略の中からどれを使うかを別途選ぶ必要がある。", "組み合わせは自動的に一意に決まるわけではなく、選定戦略によって具体的なテストケースは変わる。", "組み合わせの選定はクラシフィケーションツリー技法の中核的な要素の1つであり、存在しないという説明は誤り。", "全組み合わせ網羅は選択肢の1つにすぎず、単一値網羅やペアワイズ網羅など他の戦略を選ぶことも可能。"]}'),

  ('ctal-ta-f-q28', '組み合わせテスト',
   '組み合わせテスト（ペアワイズ等）と、クラシフィケーションツリー技法を使い分ける際の判断基準として最も適切なものはどれか。',
   NULL,
   '["入力構造が階層的（大分類の中に下位分類がある）ならクラシフィケーションツリーが、フラットな一覧ならペアワイズが向いている。", "クラシフィケーションツリーとペアワイズは互いに完全な代替技法であり、得られるテストケースは常に同一になる。", "クラシフィケーションツリーは常にペアワイズより多くのケースを生む技法であり、工数優先ならペアワイズを選ぶ。", "ペアワイズは入力が3つ以下でのみ使える技法であり、4つ以上ならクラシフィケーションツリーを使うべきである。"]', 0, '[0]', 'single',
   '{"asked": "技法選択の判断基準として、入力構造が階層的か・フラットかという観点で使い分けを理解しているか。", "kid": "入り組んだ分類（木構造）ならクラシフィケーションツリー、シンプルな一覧ならペアワイズ、という使い分け。", "terms": [["技法の使い分け", "入力の構造（階層的かフラットか）に応じて適した組み合わせ技法を選ぶこと。"]], "think": "洋服を『トップス→カジュアル/フォーマル→さらに色別』のように階層で整理したいならクラシフィケーションツリー、単純な色一覧から組み合わせを選ぶだけならペアワイズ、というイメージ。", "vs": "『常に同一の結果』『常にどちらかが多い』『入力数で機械的に決まる』は、いずれも入力構造という本質的な判断基準を無視した過度な一般化。", "opt": ["正解。階層的な構造かフラットな一覧かという入力の性質が、技法選択の実務的な判断基準になる。", "両技法は目的が近くても生成されるテストケースの構造や視点が異なり、常に同一とは限らない。", "生成されるテストケース数は入力の構造や選定戦略に依存し、どちらかが常に多いとは一概に言えない。", "入力の数だけで機械的にどちらかに決まるものではなく、階層構造の有無が実務的な判断材料になる。"]}'),

  ('ctal-ta-f-q29', 'ユースケーステスト',
   '「まなびば」のコース購入ユースケースで、『クーポンコードを入力して割引を適用し、そのまま購入を完了する』という流れと、『在庫（受講枠）切れのためエラーメッセージが表示され、購入処理が中断される』という流れがある。この2つはそれぞれ何と呼ばれるか。',
   NULL,
   '["両方とも例外フローであり、基本フロー以外の流れはすべて例外フローとしてひとまとめに扱う。", "前者は代替フロー（基本フローから分岐しつつも最終的に目的を達成する）、後者は例外フロー（目的を達成できずに終了する）。", "前者は例外フロー、後者は代替フローであり、目的を達成できるかどうかで呼び方が逆になる。", "両方とも代替フローであり、目的を達成できるかどうかによる呼び分けは行わない。"]', 1, '[1]', 'single',
   '{"asked": "代替フロー（目的達成に至る分岐）と例外フロー（目的達成に至らず終了する分岐）の違いを、具体的な事例で区別できるか。", "kid": "最終的にゴールにたどり着けるなら『別ルート（代替フロー）』、たどり着けず終わるなら『例外』。", "terms": [["代替フロー", "基本フローから分岐しつつも、最終的にユースケースの目的を達成できる流れ。"], ["例外フロー", "エラーなどにより、ユースケースの目的を達成できずに終了する流れ。"]], "think": "目的地への道で、遠回りだけどちゃんと着く道が代替フロー、途中で通行止めになって引き返す道が例外フロー。", "vs": "『両方とも代替フロー』『両方とも例外フロー』という一括りの扱いは、『目的を達成できるかどうか』という重要な区別を失わせてしまう。", "opt": ["エラーによる中断（例外フロー）と、目的を達成する分岐（代替フロー）は明確に性質が異なり、一括りにすべきではない。", "正解。目的達成の有無で、クーポン適用は代替フロー、在庫切れは例外フローと明確に区別できる。", "呼び方が逆になっている。クーポン適用は目的を達成しており代替フロー、在庫切れは達成できず例外フロー。", "目的達成の有無による区別を失うと、フローの性質（正常な分岐か、失敗による中断か）が分からなくなる。"]}'),

  ('ctal-ta-f-q30', 'ユースケーステスト',
   '「まなびば」のコース購入ユースケースをユースケーステストで一通り確認した。この場合、購入画面のクーポンコード入力欄に対して、別途、同値分割や境界値分析を適用する必要はあるか。',
   NULL,
   '["必要がある。ユースケーステストは業務フローを扱う技法であり、入力項目レベルの妥当性は別途、同値分割や境界値分析で補う。", "必要はない。業務フローを一通り確認していれば、個々の入力項目の妥当性もすべて自動的に確認されたことになる。", "必要はない。ユースケーステストと同値分割・境界値分析は完全な代替技法であり、片方があればもう片方は不要。", "必要がある。ただしこの場合、同値分割や境界値分析ではなく、状態遷移テストを追加すべきである。"]', 0, '[0]', 'single',
   '{"asked": "ユースケーステスト（業務フローレベル）と同値分割・境界値分析（入力項目レベル）が、粒度の異なる補完関係にあることを理解しているか。", "kid": "『流れ全体』を見るテストと、『1つ1つの入力欄』を見るテストは別物なので、両方必要。", "terms": [["技法の粒度", "ユースケーステストは業務フロー、同値分割・境界値分析は個々の入力項目という異なる粒度を扱う。"]], "think": "旅行全体の行程（フロー）を確認しても、個々の荷物（入力項目）の中身までは確認したことにならないのと同じ。", "vs": "『自動的に確認されたことになる』『完全な代替技法』は、粒度の異なる技法を混同した誤り。状態遷移テストへの置き換えも、入力項目レベルの確認という目的とはずれている。", "opt": ["正解。業務フローレベルと入力項目レベルは粒度が異なり、両方の技法を組み合わせて補完する必要がある。", "業務フローの確認は個々の入力項目の妥当性確認（境界値等）までは網羅せず、自動的に確認されたことにはならない。", "両技法は目的とする粒度が異なり、どちらか一方で完全に代替できる関係ではない。", "この場面で必要なのは入力項目レベルの妥当性確認であり、履歴依存の振る舞いを扱う状態遷移テストとは目的が異なる。"]}'),

  ('ctal-ta-f-q31', 'ユースケーステスト',
   '「まなびば」のコース購入ユースケースには『利用者はログイン済みであること』という事前条件がある。テスト設計として最も適切な考え方はどれか。',
   NULL,
   '["事前条件はテストの対象外として定義されているものなので、未ログイン状態の振る舞いは一切確認しなくてよい。", "事前条件が満たされているかどうかの確認は、テストアナリストではなく開発者だけが行うべき作業である。", "事前条件は基本フローの一部として扱うべきであり、代替フローや例外フローとして別立てにする必要はない。", "基本・代替フローのテストは事前条件が満たされている前提で設計しつつ、満たされていない場合の振る舞いも別途確認する。"]', 3, '[3]', 'single',
   '{"asked": "事前条件は基本フロー設計の前提として使う一方、事前条件が満たされない場合の振る舞いも別途確認すべきという実務的な判断を理解しているか。", "kid": "『ログイン済みが前提』だからといって、『ログインしてない場合どうなるか』を確認しないわけではない。", "terms": [["事前条件（precondition）", "ユースケースが正しく開始されるために満たされているべき条件。"]], "think": "『会員のみ入場可』のイベントで、会員証を前提に案内を作っても、非会員が来たときにどう対応するかは別途決めておく必要があるのと同じ。", "vs": "『一切確認不要』『開発者だけの作業』という考え方は、事前条件が満たされない状況こそテスト対象として重要であるという視点を欠いている。", "opt": ["事前条件が満たされない状況（未ログイン等）はむしろ重要なテスト対象であり、対象外とするのは見落としにつながる。", "事前条件の確認を含むテスト設計・実行はテストアナリストの通常の活動範囲であり、開発者限定の作業ではない。", "事前条件が満たされない場合の振る舞いは、基本フローとは性質が異なるため、代替・例外フローとして別立てで扱う方が整理しやすい。", "正解。事前条件は基本フローの前提として使いつつ、条件が満たされない場合の振る舞いも別途確認するのが実務的。"]}'),

  ('ctal-ta-f-q32', '経験ベース技法',
   '「探索的テストとエラー推測は同じ技法の言い換えにすぎない」という説明は正しいか。',
   NULL,
   '["正しくない。エラー推測は起こりやすい欠陥を推測する個別の技法で、探索的テストはより広いアプローチであり、複数の技法を取り込みうる。", "正しい。探索的テストとエラー推測はISTQBの用語集において全く同一の技法として定義されている用語。", "正しくない。エラー推測の方が広い概念であり、探索的テストはエラー推測の一種にすぎないという関係。", "正しい。ただし探索的テストは自動化技法、エラー推測は手動技法という点でのみ異なる関係にある。"]', 0, '[0]', 'single',
   '{"asked": "探索的テストという『広いアプローチ』と、エラー推測という『個別の技法』の包含関係を理解しているか。", "kid": "探索的テストは大きな進め方、エラー推測はその中で使える1つの道具、という関係。", "terms": [["探索的テスト", "学習・設計・実行を同時並行的に進めるテストアプローチ全体。"], ["エラー推測", "経験に基づき起こりやすい欠陥を推測する個別の技法。"]], "think": "『料理をしながら味見して調整していく』という進め方（探索的テスト）の中で、『ここは焦げやすいから注意しよう』という経験則（エラー推測）を使うようなイメージ。", "vs": "包含関係が逆になっている、あるいは自動化/手動という無関係な軸で区別しているという2種類の誤りに注意。両者は同一でも、単純にどちらかがどちらかを完全に含むという単純な話でもない（探索的テストが個別技法を取り込む広いアプローチという関係）。", "opt": ["正解。探索的テストは学習・設計・実行を同時に進める広いアプローチで、エラー推測はその中で使いうる個別技法。", "ISTQBの用語集でも、探索的テストとエラー推測はそれぞれ別の定義を持つ異なる用語として整理されている。", "包含関係が逆であり、エラー推測が探索的テストを包含する広い概念という説明は誤り。", "自動化か手動かという軸は両者を区別する本質的な違いではなく、どちらも状況に応じて手動中心で行われることが多い。"]}'),

  ('ctal-ta-f-q33', '経験ベース技法',
   '探索的テストは『行き当たりばったりで管理できないテスト』であるという批判に対する反論として最も適切なものはどれか。',
   NULL,
   '["探索的テストは管理する必要がない技法であり、管理しようとすると探索的テストではなくスクリプトテストになる。", "探索的テストの管理は、テストケースを1つ残らず事前に文書化することによってのみ可能になる方法である。", "セッションベースドテスト管理のように、チャーターを定め、時間を区切ったセッションで実施し、事後にデブリーフィングを行えば構造化して管理できる。", "探索的テストは本質的に管理不可能な活動であり、この批判は正しく、管理しようとする試みそのものが誤りである。"]', 2, '[2]', 'single',
   '{"asked": "探索的テストが『無秩序』ではなく、セッションベースドテスト管理のような枠組みで構造化・管理できることを理解しているか。", "kid": "探索的テストも、目的と時間を決めて、終わったら振り返れば、ちゃんと管理できる。", "terms": [["セッションベースドテスト管理", "チャーター（目的）を定め、時間を区切ったセッションで探索的テストを実施し、振り返る管理手法。"]], "think": "自由研究でも、テーマ（チャーター）と締め切り（セッション）を決めて、最後に発表（デブリーフィング）すれば、ちゃんとした活動として成立するのと同じ。", "vs": "『本質的に管理不可能』『管理不要』という考え方は、セッションベースドテスト管理という実務上確立された枠組みの存在を見落としている。全事前文書化はスクリプトテストの発想であり、探索的テストの管理手法とは異なる。", "opt": ["適切な範囲での管理は、探索的テストとしての性質（学習・設計・実行の同時進行）を損なわずに可能。", "全テストケースの事前文書化はスクリプトテストの考え方であり、探索的テストの管理手法としては本末転倒。", "正解。チャーター・時間区切り・デブリーフィングという枠組みにより、探索的テストも構造化して管理できる。", "セッションベースドテスト管理のような確立された枠組みがあるため、『管理不可能』という批判をそのまま認めるのは誤り。"]}'),

  ('ctal-ta-f-q34', '経験ベース技法',
   'チェックリストベーステストで使うチェックリストの項目について、最も適切な運用方針はどれか。',
   NULL,
   '["一度作成したチェックリストは、内容の正確性を保つために、その後絶対に変更してはならない。", "チェックリストの項目は、担当者が思いついた順にその場で追加していけばよく、体系的な見直しは不要である。", "自社製品の過去の欠陥データやレトロスペクティブ（振り返り）から得られた知見を反映し、定期的に項目を見直し・更新していく。", "業界の汎用テンプレートをそのまま採用し、自社製品固有の文脈に合わせた調整は一切行わない。"]', 2, '[2]', 'single',
   '{"asked": "チェックリストが自社の欠陥傾向を反映して継続的に更新されるべきものであることを理解しているか。", "kid": "『これまでの失敗から学んだこと』をリストに反映して、時々見直す。", "terms": [["レトロスペクティブ", "プロジェクトやスプリントの振り返りを行い、改善点を洗い出す活動。"]], "think": "料理の失敗ノートを見直しながら『次は焦がさないように』とチェック項目を更新していくのに似ている。", "vs": "汎用テンプレートをそのまま使う、絶対に変更しない、体系的でなく場当たり的に追加する、はいずれもチェックリストを形骸化させる運用の誤り。", "opt": ["固定化したチェックリストは新たな欠陥傾向を反映できず、時間の経過とともに形骸化してしまう。", "場当たり的な追加では体系性が失われ、重要な観点の欠落や重複が生じやすくなる。", "正解。過去の欠陥データや振り返りを反映し、定期的に見直し・更新するのが実務的に適切な運用。", "自社固有の欠陥傾向を反映しないと、汎用テンプレートでは見落としがちな自社特有のリスクに対応できない。"]}'),

  ('ctal-ta-f-q35', '経験ベース技法',
   '経験ベース技法の1つである『ソフトウェア攻撃（software attacks）』について、最も適切な説明はどれか。',
   NULL,
   '["特定の技術で起こりやすい既知の欠陥パターンや不正入力の分類に基づき、意図的に欠陥を誘発する入力を体系的に試す技法。", "システムへの実際のサイバー攻撃を代行して実施する、セキュリティ専門家向けの侵入テストそのものを指す用語。", "エラー推測と全く同じ技法を指す別名であり、両者の間に定義上の違いは特に存在しないとされる用語である。", "デシジョンテーブルを使って攻撃者の行動パターンを条件分岐として整理していく、体系立った技法である。"]', 0, '[0]', 'single',
   '{"asked": "ソフトウェア攻撃（software attacks）が、既知の欠陥パターンの分類に基づく、比較的体系立ったエラー推測の発展形であることを理解しているか。", "kid": "『こういう入力をするとよく壊れる』という決まったパターン集を使って、わざと欠陥を誘発する方法。", "terms": [["ソフトウェア攻撃（software attacks）", "既知の欠陥パターンの分類に基づき、欠陥を意図的に誘発する入力を体系的に試す経験ベース技法。"]], "think": "鍵師が『よくある鍵の弱点パターン集』を使って、意図的に弱点を突いて鍵の強度を確認するのに似ている。", "vs": "実際のサイバー攻撃の代行（侵入テストそのもの）ではなく、あくまでテスト技法としての欠陥誘発の考え方。エラー推測とは近い関係だが、既知パターンの分類に基づくという点でより体系立っている。", "opt": ["正解。既知の欠陥パターンの分類に基づいて、意図的に欠陥を誘発する入力を体系的に試すのが本技法の特徴。", "実際の不正アクセスそのものを代行する活動ではなく、あくまでテスト技法としての欠陥誘発を指す用語。", "エラー推測と関連はあるが、既知パターンの分類（タクソノミー）に基づくという点で、より体系立った技法として区別される。", "デシジョンテーブルとは異なる系統の技法であり、条件分岐の整理を主目的とするものではない。"]}'),

  ('ctal-ta-f-q36', '経験ベース技法',
   '『探索的テストはスクリプトテストと違って構造化されていないため、DDP（欠陥検出率）のようなメトリクスで効果を測定することはできない』という主張は正しいか。',
   NULL,
   '["正しい。ただしDDPの代わりに、テストケース数という別のメトリクスであれば探索的テストにも適用できる。", "正しくない。ただし探索的テストの効果は主観的な満足度アンケートでしか測定できず、客観的指標は使えない。", "正しくない。チャーターやセッション単位で記録を残せば、探索的テストでもDDPなどのメトリクスで効果を測定・比較できる。", "正しい。探索的テストは記録が一切残らない活動であるため、原理的にどのようなメトリクスも適用できない。"]', 2, '[2]', 'single',
   '{"asked": "探索的テストも適切な記録管理（セッションベース管理等）があれば、DDPのような定量的メトリクスで効果測定できることを理解しているか。", "kid": "ちゃんと記録を残せば、探索的テストでも『どれだけ見つけられたか』を数字で測れる。", "terms": [["DDP（欠陥検出率）", "テストで検出した欠陥数を、存在した欠陥の総数で割った割合。テストの効果測定に使う指標。"]], "think": "自由研究でも、やったこと・見つけたことをきちんとノートに記録すれば、後から成果を数値で振り返れるのと同じ。", "vs": "『記録が一切残らない』という前提が誤り。セッションベースドテスト管理では記録が残るため、探索的テストが原理的にメトリクス化不可能というわけではない。", "opt": ["テストケース数という指標に限定する必要はなく、記録が適切であればDDPのような欠陥検出の指標も適用できる。", "満足度アンケートのような主観指標に限定する必要はなく、記録に基づく客観的な指標も探索的テストに適用可能。", "正解。適切な記録があれば、探索的テストでもDDPのような定量的メトリクスによる効果測定・比較が可能。", "セッションベースドテスト管理などにより記録を残す運用が一般的であり、記録が一切残らないという前提は誤り。"]}'),

  ('ctal-ta-f-q37', '技法選択・メトリクス',
   '「まなびば」のコースレビュー投稿欄は自由記述のテキストで、想定外の特殊文字（絵文字・制御文字等）や極端に長い文字列の入力が懸念されている。この入力に対するテスト技法の組み合わせとして最も適切なものはどれか。',
   NULL,
   '["特殊文字の懸念は状態遷移テストの対象であり、境界値分析やエラー推測とは無関係な話である。", "文字数の上限・下限には境界値分析を、想定外の特殊文字や不正な入力パターンにはエラー推測等の経験ベース技法を組み合わせる。", "自由記述のテキストは技法を適用できない入力であり、テストを実施せず開発者の実装をそのまま信頼する。", "文字数に関する懸念であっても、デシジョンテーブルのみを使い、他の技法とは特に組み合わせない方針とする。"]', 1, '[1]', 'single',
   '{"asked": "『範囲の懸念（文字数）』には境界値分析、『パターンの懸念（特殊文字・不正入力）』には経験ベース技法、という技法の組み合わせによる判断力を理解しているか。", "kid": "『長さ』の心配には境界値分析、『変な文字』の心配には経験からの推測、というように使い分けて組み合わせる。", "terms": [["技法の組み合わせ判断", "入力の懸念点の性質（範囲かパターンか）に応じて適した技法を選び組み合わせること。"]], "think": "荷物の検査で、『重さ（範囲）』は秤で測り（境界値分析）、『危険物かどうか（パターン）』は経験に基づくチェックリストで確認する（経験ベース技法）、という役割分担に近い。", "vs": "『テスト不要』は懸念を放置する誤り。『デシジョンテーブルのみ』『状態遷移テストのみ』は、この入力の性質（数値範囲＋不正パターン）に対して技法の選び方がずれている。", "opt": ["特殊文字の懸念は入力パターンの話であり、履歴・順序に依存する状態遷移テストの主眼とは異なる。", "正解。範囲の懸念には境界値分析、パターンの懸念には経験ベース技法という組み合わせが、この入力の性質に適合する。", "自由記述であっても、文字数という範囲やパターンという性質は技法を適用してテストできる対象。", "特殊文字の懸念（パターンの問題）はデシジョンテーブル単体では捉えにくく、経験ベース技法との組み合わせがより適切。"]}'),

  ('ctal-ta-f-q38', '技法選択・メトリクス',
   '「まなびば」で『コース選択→カート追加→クーポン適用→支払い→受講開始』という、複数の画面をまたいで進む一連の業務の流れを確認したい。最も適した技法はどれか。',
   NULL,
   '["ユースケーステスト。画面をまたいだ一連の業務フロー（基本フロー・代替フロー・例外フロー）を確認するのに適している。", "境界値分析。各画面の入力項目の数値範囲を確認する技法であり、画面をまたいだ流れ全体の確認には向かない。", "デシジョンテーブル。条件の組み合わせから1つの結果を導く技法であり、複数画面にまたがる一連の流れの確認には向かない。", "クラシフィケーションツリー技法。入力の階層的な分類と組み合わせ選定が目的であり、業務フロー全体の確認には向かない。"]', 0, '[0]', 'single',
   '{"asked": "『複数画面をまたぐ一連の業務フロー』という性質に対し、ユースケーステストが最も適した技法であるという判断力を持っているか。", "kid": "いくつもの画面を順番にたどる『一連の流れ』を確認したいなら、ユースケーステストが向いている。", "terms": [["業務フロー", "複数の画面や操作をまたいで進む、一連のユーザーの行動の流れ。"]], "think": "旅行の行程表のように、複数の地点（画面）を順番にたどる全体の流れを確認したいなら、行程表そのもの（ユースケーステスト）を見るのが自然。", "vs": "境界値分析・デシジョンテーブル・クラシフィケーションツリーはいずれも個々の入力項目や条件の組み合わせに向いた技法であり、画面をまたぐ一連の流れ全体を確認する目的には合わない。", "opt": ["正解。画面をまたいだ一連の業務フローの確認には、基本/代替/例外フローを扱うユースケーステストが最も適する。", "境界値分析は個々の入力項目の範囲を確認する技法で、画面をまたぐ流れ全体の確認には向かない。", "デシジョンテーブルは条件の組み合わせから1つの結果を導く技法で、一連の業務フローの確認には向かない。", "クラシフィケーションツリーは入力の分類・組み合わせ選定が目的の技法で、業務フロー全体の確認には向かない。"]}'),

  ('ctal-ta-f-q39', '技法選択・メトリクス',
   '「まなびば」の開発プロジェクトで、実際に存在した欠陥は60件だった。単体テストで30件、結合テストで15件、システムテストで5件が検出され、残りはリリース後に利用者から報告された。テスト全体（単体＋結合＋システム）のDDP（欠陥検出率）として最も適切な値はどれか。',
   NULL,
   '["10%（リリース後に報告された欠陥の割合を、そのままDDPの値として答えてしまっている）。", "約83%（(30+15+5)÷60）。", "50%（30÷60、単体テストの検出数のみを分子として計算してしまっている）。", "90%（(30+15+5)÷50、母数を全欠陥数ではなく検出数の合計に近い数へすり替えてしまっている）。"]', 1, '[1]', 'single',
   '{"asked": "複数のテストレベルにまたがる欠陥検出数を正しく合算し、DDPの分母（全欠陥数）を正確に使って計算できるか。", "kid": "テストの各段階（単体・結合・システム）で見つけた数を全部足して、全部の欠陥数で割る。", "terms": [["DDP（欠陥検出率）", "テストで検出した欠陥数の合計を、存在した欠陥の総数で割った割合。"]], "think": "健康診断を3段階（一次・二次・三次）で受けて、それぞれで見つかった異常の合計を、実際にあった異常の総数で割って発見率を出すイメージ。", "vs": "単体テストの数だけを使う、母数を検出数の合計にすり替える、見逃した割合をそのままDDPとして答えるのは、いずれも分子・分母の取り違えによる典型的な計算ミス。", "opt": ["10%はリリース後に見逃した欠陥の割合であり、DDP（テストで検出できた割合）そのものではない。", "正解。(30+15+5)÷60＝50÷60≒83%が、3段階の検出数合計を全欠陥数で割った正しいDDP。", "単体テストの検出数だけでは、結合・システムテストで検出された分を反映できておらず、テスト全体のDDPにはならない。", "母数は実際に存在した欠陥の総数（60件）であり、検出数の合計に近い数（50）にすり替えるのは誤り。"]}'),

  ('ctal-ta-f-q40', '技法選択・メトリクス',
   '決済ロジックのように非常にリスクが高く、複数の独立した条件が複雑に絡み合って結果が決まる機能に対して、最も適した技法の組み合わせはどれか。',
   NULL,
   '["デシジョンテーブルを中心に据えて条件の組み合わせを網羅し、金額など数値の入力項目には境界値分析を併用する。", "状態遷移テストのみを使い、条件の組み合わせについては特に技法を用いずテスト担当者の判断に委ねる。", "ペアワイズテストのみを使い、リスクの高さにかかわらず組み合わせ数を最小限に抑えることを最優先する。", "探索的テストのみを使い、事前の技法に基づく設計は行わずにその場の判断だけで確認する。"]', 0, '[0]', 'single',
   '{"asked": "『高リスク＋複数条件の組み合わせ』という性質に対し、デシジョンテーブル（＋境界値分析の併用）が適した技法選択であるという総合的な判断力を持っているか。", "kid": "リスクが高くて条件がいろいろ絡むところは、組み合わせをしっかり表にして（デシジョンテーブル）、数値の部分は境界値分析も足す。", "terms": [["技法の組み合わせによるリスク対応", "高リスクな機能ほど、複数の技法を組み合わせて網羅度を高める。"]], "think": "重要な契約書を確認するとき、条件ごとにチェック表を作り（デシジョンテーブル）、金額欄は特に細かく確認する（境界値分析）、という念入りな確認の仕方に近い。", "vs": "状態遷移テストは順序・履歴依存の振る舞いに適した技法で、単純な条件組み合わせには過剰または不適合。ペアワイズは組み合わせ爆発を抑える技法で、高リスク領域で網羅度より削減を優先するのは方針として逆行。探索的テストのみに頼ると、高リスク領域での体系的な網羅性が確保しにくい。", "opt": ["正解。デシジョンテーブルで条件の組み合わせを網羅し、数値項目には境界値分析を併用するのが高リスク機能への適切な対応。", "状態遷移テストは順序・履歴依存の振る舞いに向いた技法であり、複数条件の組み合わせが中心のこの機能には適合しにくい。", "高リスクな機能でこそ網羅度を優先すべきで、組み合わせ数の削減を最優先するペアワイズ単独は方針として逆行する。", "探索的テストのみでは体系的な網羅性が確保しにくく、高リスクな決済ロジックには設計に基づく技法の併用が望ましい。"]}')

) AS v(source_ref, cat_name, question_text, code, options, correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.cat_name
WHERE s.slug = 'ctal-ta-f'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
